    border-radius:14px;padding:24px 26px 26px;transition:border-color .15s,box-shadow .15s}
  .job:hover{border-color:#b3bdcf;box-shadow:0 10px 24px -14px rgba(18,33,59,.28)}
  .job h2{margin:0 0 8px;font-family:var(--display);font-size:22px;font-weight:700;letter-spacing:-.02em;line-height:1.2}
