const shell = (title, body) => `<!DOCTYPE html>
<html lang="en"><head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1">
<title>${title} - Shortlist</title>
<link rel="preconnect" href="https://fonts.googleapis.com">
<link rel="preconnect" href="https://fonts.gstatic.com" crossorigin>
<link href="https://fonts.googleapis.com/css2?family=Bricolage+Grotesque:opsz,wght@12..96,500..800&family=Instrument+Sans:wght@400..700&display=swap" rel="stylesheet">
<style>${SHELL_CSS}</style></head><body>
<header class="bar"><div class="bar__in">
  <span class="brand">
    <svg viewBox="0 0 32 32" aria-hidden="true">
      <rect width="32" height="32" rx="8" fill="#12213B"/>
      <rect x="9" y="6" width="14" height="20" rx="2" fill="#F7F8FB"/>
      <rect x="11.5" y="10" width="9" height="2" rx="1" fill="#9AA6BA"/>
      <rect x="8" y="14.5" width="16" height="4.5" rx="1" fill="#FFD93D" opacity=".92"/>
      <rect x="11.5" y="15.5" width="9" height="2" rx="1" fill="#12213B"/>
      <rect x="11.5" y="21" width="6" height="2" rx="1" fill="#9AA6BA"/>
    </svg>
    Shortlist
  </span>
</div></header>
<main>${body}</main>
</body></html>`;

const esc = (s) => String(s ?? "").replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));

const jobs = $('Get Jobs').all().map(i => i.json)
  .filter(j => j && j.jobId && String(j.status).trim() === "Open");

const cards = jobs.map(j => {
  const exp = Number(j.minExperienceYears) > 0 ? '<span class="tag tag--exp">' + esc(j.minExperienceYears) + '+ years experience</span>' : '';
  const edu = j.education ? '<span class="tag">' + esc(j.education) + '</span>' : '';
  return '<article class="job">' +
    '<h2>' + esc(j.role) + '</h2>' +
    '<div class="tags">' + (exp + edu || '<span class="tag">Details in the job post</span>') + '</div>' +
    '<button class="btn" data-job="' + esc(String(j.jobId).trim()) + '">View job</button>' +
    '</article>';
}).join("");

const body = '<p class="eyebrow">Join our team</p>' +
  '<h1>Open positions</h1>' +
  '<p class="lede">Browse the roles we are hiring for and find the one that fits you.</p>' +
  (cards
    ? '<div class="grid">' + cards + '</div>'
    : '<div class="empty"><h2>No open positions right now</h2>Please check back soon.</div>') +
  '<script>' +
  'document.addEventListener("click", function(e){' +
  '  var id = e.target.getAttribute("data-job");' +
  '  if (!id) return;' +
  '  var parts = location.pathname.split("/"); parts.pop();' +
  '  location.href = parts.join("/") + "/post?jobId=" + encodeURIComponent(id);' +
  '});' +
  '</script>';

return [{ json: { html: shell("Open positions", body) } }];

