    Shortlist
  </span>
  <a class="back" href="javascript:history.back()">← All positions</a>
</div></header>
<main>${body}</main>
</body></html>`;

const esc = (s) => String(s ?? "").replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));

const params = $('Post Page').first().json.query || {};
const job = $('Get Post Job').first().json || {};
const wanted = String(params.jobId || "").trim().toUpperCase();
const isOpen = Boolean(job.jobId) && String(job.jobId).trim().toUpperCase() === wanted && String(job.status).trim() === "Open";

if (!isOpen) {
  return [{ json: { html: shell("Position unavailable",
    '<div class="unavailable"><h1>This position is no longer available</h1><p>The job may have closed, or the link is not valid.</p><a class="btn btn--inline" href="javascript:history.back()">Back to open positions</a></div>') } }];
}

let post = null;
try {
  const p = JSON.parse(job.webPost || "");
  if (p && typeof p === "object") post = p;
} catch (e) { post = null; }

const list = (v, max) => Array.isArray(v) ? v.map(x => String(x || "").trim()).filter(Boolean).slice(0, max) : [];

const headline = (post && post.headline) ? String(post.headline) : String(job.role || "");
const summary = (post && post.summary) ? String(post.summary) : "";
const duties = post ? list(post.responsibilities, 6) : [];
let requirements = post ? list(post.requirements, 14) : [];
if (!requirements.length) {
  requirements = [Number(job.minExperienceYears) > 0 ? job.minExperienceYears + "+ years of professional experience" : "", job.education || ""].filter(Boolean);
}
const nice = post ? list(post.nice_to_have, 8) : [];
const location = (post && post.location) ? String(post.location) : "";

const link = String(job.applyLink || "").trim();
const applyHref = /^https:\/\//.test(link) ? link : "#";

const chips = [
  location ? '<span class="chip">' + esc(location) + '</span>' : '',
  Number(job.minExperienceYears) > 0 ? '<span class="chip chip--hl">' + esc(job.minExperienceYears) + '+ years</span>' : '',
  job.education ? '<span class="chip">' + esc(job.education) + '</span>' : ''
].filter(Boolean).join("");

const ul = (items) => '<ul class="list">' + items.map(i => '<li>' + esc(i) + '</li>').join("") + '</ul>';

const facts = [
  location ? ['Location', location] : null,
  Number(job.minExperienceYears) > 0 ? ['Experience', job.minExperienceYears + '+ years'] : null,
  job.education ? ['Education', job.education] : null,
].filter(Boolean).map(([k, v]) => '<div class="fact"><dt>' + k + '</dt><dd>' + esc(v) + '</dd></div>').join("");

const body = '<p class="eyebrow">Open position</p>' +
  '<h1>' + esc(headline) + '</h1>' +
  (chips ? '<div class="chips">' + chips + '</div>' : '') +
  '<div class="layout">' +
    '<article class="card">' +
      (summary ? '<p class="summary">' + esc(summary) + '</p>' : '') +
      (duties.length ? '<h2>What you will do</h2>' + ul(duties) : '') +
      (requirements.length ? '<h2>What we are looking for</h2>' + ul(requirements) : '') +
      (nice.length ? '<h2>Nice to have</h2>' + ul(nice) : '') +
    '</article>' +
    '<aside class="side">' +
      '<h2>Role details</h2>' +
      (facts ? '<dl>' + facts + '</dl>' : '') +
      '<a class="btn" href="' + esc(applyHref) + '"' + (applyHref === '#' ? ' aria-disabled="true"' : '') + '>Apply for this role</a>' +
      '<p class="note">You will be asked for your CV and contact details.</p>' +
    '</aside>' +
  '</div>';

return [{ json: { html: shell(esc(job.role), body) } }];

