const esc = (s) => String(s ?? "").replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));

const openJobs = $('Get Jobs For Skills').all().map(i => i.json)
  .filter(j => j && j.jobId && String(j.status).trim() === "Open");
const openIds = new Set(openJobs.map(j => String(j.jobId).trim()));

const rows = $('Get Skill Rows').all().map(i => i.json)
  .filter(r => r && r.skill && openIds.has(String(r.jobId).trim()));

const norm = (s) => String(s).trim().replace(/\s+/g, " ");
const keyOf = (s) => norm(s).toLowerCase();

// Skill demand: how many distinct open jobs ask for each skill
const demand = new Map();
for (const r of rows) {
  const k = keyOf(r.skill);
  if (!demand.has(k)) demand.set(k, { name: norm(r.skill), required: new Set(), nice: new Set() });
  const d = demand.get(k);
  const isNice = String(r.type || "").trim().toLowerCase() === "nice-to-have";
  (isNice ? d.nice : d.required).add(String(r.jobId).trim());
}
const topSkills = [...demand.values()]
  .map(d => ({ name: d.name, required: d.required.size, nice: d.nice.size }))
  .sort((a, b) => (b.required + b.nice) - (a.required + a.nice))
  .slice(0, 12);

const requiredTotal = rows.filter(r => String(r.type || "").trim().toLowerCase() !== "nice-to-have").length;
const niceTotal = rows.length - requiredTotal;

// Per role: open jobs, average experience and most requested skills
const roles = new Map();
for (const j of openJobs) {
  const role = norm(j.role || "Other");
  if (!roles.has(role)) roles.set(role, { role, jobs: 0, years: [], skills: new Map() });
  roles.get(role).jobs++;
  if (Number(j.minExperienceYears) > 0) roles.get(role).years.push(Number(j.minExperienceYears));
}
const roleOf = {};
openJobs.forEach(j => { roleOf[String(j.jobId).trim()] = norm(j.role || "Other"); });
const skillName = {};
for (const r of rows) {
  const role = roleOf[String(r.jobId).trim()];
  if (!role || !roles.has(role)) continue;
  const m = roles.get(role).skills;
  const k = keyOf(r.skill);
  m.set(k, (m.get(k) || 0) + 1);
  skillName[k] = norm(r.skill);
}
const roleRows = [...roles.values()].map(r => ({
  role: r.role,
  jobs: r.jobs,
  avgYears: r.years.length ? Math.round((r.years.reduce((a, b) => a + b, 0) / r.years.length) * 10) / 10 : 0,
  topSkills: [...r.skills.entries()].sort((a, b) => b[1] - a[1]).slice(0, 4).map(([k]) => skillName[k])
})).sort((a, b) => b.jobs - a.jobs);

// Trend: open jobs posted per week, last 8 weeks (weeks start on Monday)
const weekCount = new Map();
for (const j of openJobs) {
  const d = new Date(j.createdAt);
  if (isNaN(d)) continue;
  const day = (d.getUTCDay() + 6) % 7;
  const mon = new Date(Date.UTC(d.getUTCFullYear(), d.getUTCMonth(), d.getUTCDate() - day));
  const key = mon.toISOString().slice(0, 10);
  weekCount.set(key, (weekCount.get(key) || 0) + 1);
}
const weeks = [...weekCount.entries()].sort((a, b) => a[0] < b[0] ? -1 : 1).slice(-8)
  .map(([week, count]) => ({ week, count }));
const postedRecently = weeks.reduce((sum, w) => sum + w.count, 0);

const ys = openJobs.map(j => Number(j.minExperienceYears)).filter(y => y > 0);
const avgAll = ys.length ? Math.round((ys.reduce((a, b) => a + b, 0) / ys.length) * 10) / 10 : 0;

const DATA = { demand: topSkills, roles: roleRows, weeks, required: requiredTotal, nice: niceTotal };
const dataJs = JSON.stringify(DATA).replace(/</g, "\\u003c");

const roleTable = roleRows.length
  ? '<div style="overflow-x:auto"><table style="min-width:620px"><thead><tr><th>Role</th><th>Open jobs</th><th>Min. experience</th><th>Most requested skills</th></tr></thead><tbody>' +
    roleRows.map(r => '<tr><td class="role">' + esc(r.role) + '</td><td class="num">' + r.jobs + '</td><td>' +
      (r.avgYears ? esc(r.avgYears) + ' years' : '<span class="muted">Not stated</span>') + '</td><td>' +
      (r.topSkills.map(s => '<span class="pill">' + esc(s) + '</span>').join("") || '<span class="muted">—</span>') + '</td></tr>').join("") +
    '</tbody></table></div>'
  : '<div class="none">No open positions yet.</div>';

const body =
  '<p class="eyebrow">Live view of our hiring</p>' +
  '<h1>Skills in demand</h1>' +
  '<p class="lede">See what our open positions look for. Use it to focus your learning and to tailor your CV.</p>' +

  '<div class="kpis">' +
    '<div class="kpi kpi--hl"><div class="kpi__label">Open positions</div><div class="kpi__value">' + openJobs.length + '</div></div>' +
    '<div class="kpi"><div class="kpi__label">Skills requested</div><div class="kpi__value">' + demand.size + '</div></div>' +
    '<div class="kpi"><div class="kpi__label">Average experience</div><div class="kpi__value">' + (avgAll ? esc(avgAll) + ' yrs' : '—') + '</div></div>' +
    '<div class="kpi"><div class="kpi__label">Posted in the last 8 weeks</div><div class="kpi__value">' + postedRecently + '</div></div>' +
  '</div>' +

  '<div class="section-head"><h2>Top skills</h2><p>How many open positions ask for each skill, split by required and nice to have.</p></div>' +
  '<div class="split">' +
    '<section class="card"><div class="chart" style="height:' + Math.max(260, topSkills.length * 36 + 60) + 'px"><canvas id="demand"></canvas></div>' +
      '<div class="legend"><span><i style="background:#12213b"></i>Required</span><span><i style="background:#ffd93d"></i>Nice to have</span></div></section>' +
    '<section class="card"><div class="card__head"><h2 style="font-size:18px">Required or nice to have</h2><p>Share of all skill requests</p></div>' +
      '<div class="chart" style="height:240px"><canvas id="split"></canvas></div><div class="legend" style="justify-content:center"><span><i style="background:#12213b"></i>Required</span><span><i style="background:#ffd93d"></i>Nice to have</span></div></section>' +
  '</div>' +

  '<div class="section-head"><h2>Roles and experience</h2><p>What each open role asks for, and how many years of experience it needs.</p></div>' +
  '<div class="pair">' +
    '<section class="card"><div class="card__head"><h2 style="font-size:18px">Minimum experience by role</h2><p>Years required, per role</p></div>' +
      '<div class="chart" style="height:280px"><canvas id="years"></canvas></div></section>' +
    '<section class="card"><div class="card__head"><h2 style="font-size:18px">New positions per week</h2><p>Open positions posted, last 8 weeks</p></div>' +
      '<div class="chart" style="height:280px"><canvas id="trend"></canvas></div></section>' +
  '</div>' +

  '<div class="section-head"><h2>Roles at a glance</h2></div>' +
  '<section class="card" style="padding:14px 18px">' + roleTable + '</section>' +

  '<p class="footnote">Figures come from our open positions and change as roles open and close.</p>' +

  '<script src="https://cdnjs.cloudflare.com/ajax/libs/Chart.js/4.4.1/chart.umd.min.js"></script>' +
  '<script>' +
  'var DATA = ' + dataJs + ';' +
  'var INK = "#12213b", YELLOW = "#ffd93d", GREEN = "#075e4b", BLUE = "#1e40af", VIOLET = "#5b21b6", STEEL = "#56657e", LINE = "#e6ebf3";' +
  'Chart.defaults.font.family = "Instrument Sans, system-ui, sans-serif";' +
  'Chart.defaults.color = STEEL;' +
  'Chart.defaults.plugins.legend.display = false;' +
  'Chart.defaults.plugins.tooltip.backgroundColor = INK;' +
  'Chart.defaults.plugins.tooltip.padding = 10;' +
  'Chart.defaults.plugins.tooltip.cornerRadius = 8;' +
  'function empty(id){ var c = document.getElementById(id); c.parentNode.innerHTML = \'<div class="none">Not enough data yet.</div>\'; }' +

  'if (DATA.demand.length) {' +
    'new Chart(document.getElementById("demand"), {type: "bar", data: {labels: DATA.demand.map(function(d){ return d.name; }), datasets: [' +
      '{label: "Required", data: DATA.demand.map(function(d){ return d.required; }), backgroundColor: INK, borderRadius: 6, borderSkipped: false, barThickness: 18},' +
      '{label: "Nice to have", data: DATA.demand.map(function(d){ return d.nice; }), backgroundColor: YELLOW, borderRadius: 6, borderSkipped: false, barThickness: 18}]},' +
      'options: {indexAxis: "y", responsive: true, maintainAspectRatio: false, plugins: {legend: {display: false}},' +
        'scales: {x: {stacked: true, beginAtZero: true, ticks: {precision: 0}, grid: {color: LINE}, border: {display: false}},' +
                 'y: {stacked: true, grid: {display: false}, border: {display: false}, ticks: {color: INK, font: {weight: "600"}}}}}});' +
  '} else { empty("demand"); }' +

  'if (DATA.required + DATA.nice) {' +
    'new Chart(document.getElementById("split"), {type: "doughnut", data: {labels: ["Required", "Nice to have"], datasets: [{data: [DATA.required, DATA.nice], backgroundColor: [INK, YELLOW], borderWidth: 0}]},' +
      'options: {responsive: true, maintainAspectRatio: false, cutout: "68%", plugins: {legend: {display: false}}}});' +
  '} else { empty("split"); }' +

  'if (DATA.roles.length) {' +
    'new Chart(document.getElementById("years"), {type: "bar", data: {labels: DATA.roles.map(function(r){ return r.role; }), datasets: [' +
      '{label: "Years", data: DATA.roles.map(function(r){ return r.avgYears; }), backgroundColor: GREEN, borderRadius: 8, borderSkipped: false, barThickness: 28}]},' +
      'options: {responsive: true, maintainAspectRatio: false, scales: {y: {beginAtZero: true, grid: {color: LINE}, border: {display: false}, ticks: {precision: 0}}, x: {grid: {display: false}, border: {display: false}}}}});' +
  '} else { empty("years"); }' +

  'if (DATA.weeks.length) {' +
    'new Chart(document.getElementById("trend"), {type: "line", data: {labels: DATA.weeks.map(function(w){ return w.week; }), datasets: [' +
      '{label: "Positions", data: DATA.weeks.map(function(w){ return w.count; }), borderColor: VIOLET, backgroundColor: "rgba(91,33,182,.12)", fill: true, tension: .35, pointRadius: 4, pointBackgroundColor: VIOLET, pointBorderWidth: 0}]},' +
      'options: {responsive: true, maintainAspectRatio: false, scales: {y: {beginAtZero: true, grid: {color: LINE}, border: {display: false}, ticks: {precision: 0}}, x: {grid: {display: false}, border: {display: false}}}}});' +
  '} else { empty("trend"); }' +
  '</script>';

return [{ json: { html: shell("Skills in demand", body) } }];
